export function createLedger() {
  let total = 0;
  const receipts = new Map<string, {id: string; amount: number; balance: number}>();
  return {
    balance: () => total,
    async settle(id: string, amount: number) {
      if (typeof id !== 'string' || id.length === 0 || !Number.isSafeInteger(amount) || amount <= 0) {
        throw new Error('invalid');
      }
      const existing = receipts.get(id);
      if (existing) {
        if (existing.amount !== amount) throw new Error('amount conflict');
        return existing;
      }
      const nextTotal = total + amount;
      if (!Number.isSafeInteger(nextTotal)) throw new Error('balance overflow');
      const receipt = { id, amount, balance: nextTotal };
      receipts.set(id, receipt);
      total = nextTotal;
      return receipt;
    }
  };
}

